import { mutation } from "flarex/server";
import { v } from "flarex/values";
import { write } from "../functions/records.js";
export default { records: { write: mutation({ args: { scores: v.record(v.string(), v.number()) }, returns: v.record(v.string(), v.number()), handler: write }) } };

import { defineGlobalTable, defineSchema } from "flarex/server";
import { v } from "flarex/values";
export default defineSchema({ users: defineGlobalTable({ name: v.string() }).index("by_name", ["name"]), recordDocs: defineGlobalTable({ scores: v.record(v.string(), v.number()) }) });
